<script setup lang="ts">
import { computed,nextTick,onMounted,onUnmounted,ref } from 'vue'
import type { ComponentPublicInstance } from 'vue'
import { CalendarDays,ChevronLeft,ChevronRight,Clock3,Download,Film,RefreshCw,Volume2 } from '@lucide/vue'
import { api,bytes,type Observation } from '../services/api'
import '../drive-playback.css'
import CameraViewSwitch from './CameraViewSwitch.vue'

type Camera='front'|'in'
type ViewMode=Camera|'both'
type Clip={id:string;name:string;camera:Camera;kind?:string;startAt:string;endAt:string;durationSeconds:number;sizeBytes:string;videoCodec?:string;audioCodec?:string;width?:number;height?:number}
type Day={date:string;count:number;frontCount:number;cabinCount:number;recordedSeconds:number}
type Catalog={clips:Clip[];days:Day[];pendingFiles:number;unreadableFiles:number;truncated:boolean;timezone:string;indexedAt:string}
const catalog=ref<Catalog>(),loading=ref(true),error=ref(''),notice=ref(''),viewMode=ref<ViewMode>('front'),speed=ref(1),zoomHours=ref(24),cursor=ref(0),windowStart=ref(0),playing=ref(false),calendarOpen=ref(false)
const selectedDate=ref(todayJST()),month=ref(selectedDate.value.slice(0,7)),selected=ref<Record<Camera,Clip|null>>({front:null,in:null}),playIntent=ref(false)
const videoElements:Partial<Record<Camera,HTMLVideoElement>>={};const targetOffsets:Partial<Record<Camera,number>>={};let fetchVersion=0;let refreshTimer:ReturnType<typeof setInterval>|undefined;let pointer: {camera:Camera;target:HTMLElement;id:number;time:number}|undefined
const cameraNames:Record<Camera,string>={front:'前方カメラ',in:'車内カメラ'}
const weekday=['日','月','火','水','木','金','土']
function todayJST(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function dayStart(date:string){return Date.parse(date+'T00:00:00+09:00')}
function clock(ms:number,seconds=false){return new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',...(seconds?{second:'2-digit'}:{}),hourCycle:'h23'}).format(new Date(ms))}
function dayLabel(date:string){return new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'long',day:'numeric',weekday:'short'}).format(new Date(dayStart(date)))}
function duration(seconds:number){const minutes=Math.floor(seconds/60);return minutes>=60?`${Math.floor(minutes/60)}時間${minutes%60}分`:`${minutes}分${Math.floor(seconds%60)}秒`}
function kindLabel(kind?:string){return kind==='event'?'イベント':kind==='parking'?'駐車':'通常録画'}
const selectedDay=computed(()=>catalog.value?.days.find(d=>d.date===selectedDate.value))
const allDayClips=computed(()=>{const from=dayStart(selectedDate.value),to=from+86400000;return (catalog.value?.clips||[]).filter(c=>Date.parse(c.startAt)<to&&Date.parse(c.endAt)>from)})
const cameras=computed<Camera[]>(()=>viewMode.value==='both'?['front','in']:[viewMode.value])
const primary=computed<Camera>(()=>viewMode.value==='in'?'in':viewMode.value==='both'&&!selected.value.front&&selected.value.in?'in':'front')
const span=computed(()=>zoomHours.value*3600000)
const endOfWindow=computed(()=>windowStart.value+span.value)
const cursorPercent=computed(()=>Math.max(0,Math.min(100,(cursor.value-windowStart.value)/span.value*100)))
const ticks=computed(()=>Array.from({length:7},(_,i)=>({left:i/6*100,label:windowStart.value+span.value*i/6===dayStart(selectedDate.value)+86400000?'24:00':clock(windowStart.value+span.value*i/6)})))
const monthLabel=computed(()=>`${Number(month.value.slice(0,4))}年 ${Number(month.value.slice(5))}月`)
const calendarDays=computed(()=>{const [year,monthNumber]=month.value.split('-').map(Number),first=new Date(Date.UTC(year,monthNumber-1,1)),count=new Date(Date.UTC(year,monthNumber,0)).getUTCDate();const result:Array<{date:string;day:number;data?:Day}|null>=Array.from({length:first.getUTCDay()},()=>null);const days=new Map((catalog.value?.days||[]).map(d=>[d.date,d]));for(let n=1;n<=count;n++){const date=`${year}-${String(monthNumber).padStart(2,'0')}-${String(n).padStart(2,'0')}`;result.push({date,day:n,data:days.get(date)})}return result})
const availableSpans=computed(()=>{const bounds=allDayClips.value.map(c=>({start:Math.max(dayStart(selectedDate.value),Date.parse(c.startAt)),end:Math.min(dayStart(selectedDate.value)+86400000,Date.parse(c.endAt))})).sort((a,b)=>a.start-b.start);const result:{start:number;end:number}[]=[];for(const b of bounds){const last=result.at(-1);if(last&&b.start<=last.end+1000){last.end=Math.max(last.end,b.end)}else{result.push({...b})}}return result})
function moveMonth(delta:number){const [year,m]=month.value.split('-').map(Number),date=new Date(Date.UTC(year,m-1+delta,1));month.value=`${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}`}
async function load(){
 const version=++fetchVersion;loading.value=true;error.value=''
 try{
  let value=await api<Observation<Catalog>>('/recordings?date='+selectedDate.value)
  if(version!==fetchVersion)return
  const previousIDs=Object.values(selected.value).filter((clip):clip is Clip=>!!clip).map(clip=>clip.id),wasEmpty=!cursor.value
  if(wasEmpty&&!value.data.days.some(d=>d.date===selectedDate.value)&&value.data.days.length){
   selectedDate.value=value.data.days[0].date;month.value=selectedDate.value.slice(0,7)
   value=await api<Observation<Catalog>>('/recordings?date='+selectedDate.value)
   if(version!==fetchVersion)return
  }
  catalog.value=value.data
  if(wasEmpty){windowStart.value=dayStart(selectedDate.value);const first=allDayClips.value[0];if(first)await seekAvailable(Math.max(dayStart(selectedDate.value),Date.parse(first.startAt)),false);else cursor.value=dayStart(selectedDate.value);focusFirstInterval()}
  else if(previousIDs.some(id=>!value.data.clips.some(clip=>clip.id===id))){pauseAll();await seekAt(cursor.value,false);notice.value='SDカードまたは録画が更新されました。再生する時刻を選び直してください。'}
 }catch(e){if(version===fetchVersion)error.value=e instanceof Error?e.message:String(e)}
 finally{if(version===fetchVersion)loading.value=false}
}
async function chooseDay(date:string){pauseAll();selectedDate.value=date;month.value=date.slice(0,7);calendarOpen.value=false;windowStart.value=dayStart(date);zoomHours.value=24;selected.value={front:null,in:null};notice.value='';cursor.value=dayStart(date);await load();const first=allDayClips.value[0];if(first)await seekAvailable(Math.max(cursor.value,Date.parse(first.startAt)),false);focusFirstInterval()}
function streamURL(clip:Clip){return '/api/v1/recordings/'+encodeURIComponent(clip.id)+'/stream'}
function downloadURL(clip:Clip){return '/api/v1/recordings/'+encodeURIComponent(clip.id)+'/download'}
function setVideo(camera:Camera,element:Element|ComponentPublicInstance|null){if(element instanceof HTMLVideoElement)videoElements[camera]=element;else delete videoElements[camera]}
function clipAt(camera:Camera,time:number){return allDayClips.value.reduce<Clip|null>((best,clip)=>clip.camera===camera&&Date.parse(clip.startAt)<=time&&Date.parse(clip.endAt)>time&&(!best||Date.parse(clip.startAt)>Date.parse(best.startAt))?clip:best,null)}
function seekAvailable(time:number,play=true){const camera:Camera=clipAt('front',time)?'front':'in';return seekAt(time,play,camera)}
function focusFirstInterval(){const interval=availableSpans.value[0];if(!interval)return;zoomHours.value=interval.end-interval.start<=900000?.25:1;changeZoom()}
function ensureWindow(time:number){const start=dayStart(selectedDate.value),maxStart=start+86400000-span.value;if(time<windowStart.value||time>=endOfWindow.value){windowStart.value=Math.min(maxStart,Math.max(start,time-span.value/3))}}
async function seekAt(time:number,play=true,camera?:Camera){time=Math.max(dayStart(selectedDate.value),Math.min(dayStart(selectedDate.value)+86400000-1,time));if(camera&&viewMode.value!=='both')viewMode.value=camera;cursor.value=time;playIntent.value=play;notice.value='';ensureWindow(time);const next={front:clipAt('front',time),in:clipAt('in',time)};for(const c of ['front','in'] as Camera[]){const clip=next[c];if(clip)targetOffsets[c]=Math.max(0,(time-Date.parse(clip.startAt))/1000)}selected.value=next;await nextTick();for(const camera of cameras.value){const element=videoElements[camera];if(element&&element.readyState>=1)metadataReady(camera)}if(!next[primary.value]){playing.value=false;notice.value='この時刻には、選択したカメラの録画がありません。青・橙の録画区間を選んでください。'}}
function metadataReady(camera:Camera){const video=videoElements[camera],clip=selected.value[camera];if(!video||!clip)return;const target=targetOffsets[camera];if(target!==undefined){video.currentTime=Math.max(0,Math.min(clip.durationSeconds-.01,target));delete targetOffsets[camera]}video.playbackRate=speed.value;if(playIntent.value)video.play().catch(()=>{if(camera===primary.value)notice.value='再生ボタンを押して映像・音声を開始してください。'})}
function pauseAll(){playIntent.value=false;playing.value=false;for(const v of Object.values(videoElements))v.pause()}
function primaryPlay(camera:Camera){if(camera!==primary.value)return;playing.value=true;playIntent.value=true;for(const c of cameras.value){if(c!==camera)videoElements[c]?.play().catch(()=>{})}}
function primaryPause(camera:Camera){if(camera!==primary.value)return;playing.value=false;for(const c of cameras.value){if(c!==camera)videoElements[c]?.pause()}}
function updateTime(camera:Camera){if(camera!==primary.value||pointer)return;const video=videoElements[camera],clip=selected.value[camera];if(!video||!clip)return;const time=Date.parse(clip.startAt)+video.currentTime*1000;cursor.value=time;ensureWindow(time);if(viewMode.value==='both'){const other:Camera=camera==='front'?'in':'front',otherClip=clipAt(other,time);if(otherClip?.id!==selected.value[other]?.id){selected.value={...selected.value,[other]:otherClip};if(otherClip)targetOffsets[other]=(time-Date.parse(otherClip.startAt))/1000}else{const otherVideo=videoElements[other];if(otherVideo&&otherClip){const target=(time-Date.parse(otherClip.startAt))/1000;if(Math.abs(otherVideo.currentTime-target)>.6)otherVideo.currentTime=target}}}}
function nextClip(direction:number){const starts=[...new Set(allDayClips.value.filter(c=>viewMode.value==='both'||c.camera===viewMode.value).map(c=>Date.parse(c.startAt)))].sort((a,b)=>a-b);const value=direction>0?starts.find(t=>t>cursor.value+1000):starts.slice().reverse().find(t=>t<cursor.value-1000);if(value!==undefined)seekAt(Math.max(dayStart(selectedDate.value),value),true)}
function ended(camera:Camera){if(camera!==primary.value)return;const clip=selected.value[camera];if(!clip)return;const end=Date.parse(clip.endAt),next=allDayClips.value.find(c=>c.camera===camera&&Date.parse(c.startAt)>Date.parse(clip.startAt)&&Date.parse(c.endAt)>end&&Date.parse(c.startAt)<=end+2000);if(next)seekAt(Math.max(end,Date.parse(next.startAt)),true);else{playing.value=false;playIntent.value=false}}
function changeView(){seekAt(cursor.value,playing.value)}
function changeSpeed(){for(const v of Object.values(videoElements))v.playbackRate=speed.value}
function changeZoom(){const start=dayStart(selectedDate.value);windowStart.value=Math.max(start,Math.min(start+86400000-span.value,cursor.value-span.value/2))}
function clipStyle(clip:Clip){const from=Math.max(windowStart.value,Date.parse(clip.startAt)),to=Math.min(endOfWindow.value,Date.parse(clip.endAt));return {left:((from-windowStart.value)/span.value*100)+'%',width:Math.max(.1,(to-from)/span.value*100)+'%'}}
function visibleClips(camera:Camera){return allDayClips.value.filter(c=>c.camera===camera&&Date.parse(c.startAt)<endOfWindow.value&&Date.parse(c.endAt)>windowStart.value)}
function pointTime(event:PointerEvent,target:HTMLElement){const rect=target.getBoundingClientRect();return windowStart.value+Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width))*span.value}
function pointerDown(event:PointerEvent,camera:Camera){const target=event.currentTarget as HTMLElement;pointer={camera,target,id:event.pointerId,time:pointTime(event,target)};target.setPointerCapture(event.pointerId);cursor.value=pointer.time}
function pointerMove(event:PointerEvent){if(!pointer||pointer.id!==event.pointerId)return;pointer.time=pointTime(event,pointer.target);cursor.value=pointer.time}
function pointerUp(event:PointerEvent){if(!pointer||pointer.id!==event.pointerId)return;const {camera,time,target}=pointer;pointer=undefined;target.releasePointerCapture(event.pointerId);seekAt(time,true,camera)}
function keySeek(event:KeyboardEvent,camera:Camera){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let value=cursor.value+(event.key==='ArrowLeft'?-1:1)*(event.shiftKey?60:10)*1000;if(event.key==='Home')value=dayStart(selectedDate.value);if(event.key==='End')value=dayStart(selectedDate.value)+86400000-1;seekAt(value,false,camera)}
function timeInput(event:Event){const value=(event.target as HTMLInputElement).value;if(!/^\d\d:\d\d(:\d\d)?$/.test(value))return;const [h,m,s=0]=value.split(':').map(Number);seekAt(dayStart(selectedDate.value)+(h*3600+m*60+s)*1000,true)}
onMounted(()=>{load();refreshTimer=setInterval(()=>{if(!document.hidden)load()},30000)})
onUnmounted(()=>{fetchVersion++;if(refreshTimer)clearInterval(refreshTimer);pauseAll()})
</script>

<template>
 <div class="drive-toolbar"><div><h2>{{dayLabel(selectedDate)}}</h2><span>{{selectedDay?`${selectedDay.count} 本 · ${duration(selectedDay.recordedSeconds)}の記録`:'この日の確定録画はありません'}}</span></div><button class="secondary compact" :disabled="loading" @click="load"><RefreshCw :size="14" :class="{spinning:loading}"/>{{loading?'更新中…':'更新'}}</button></div>
 <div v-if="error" class="banner error" role="alert">{{error}} <button class="text-button" @click="load">再試行</button></div>
 <div class="drive-layout">
  <aside class="drive-sidebar">
   <button class="drive-calendar-toggle" @click="calendarOpen=!calendarOpen" :aria-expanded="calendarOpen"><CalendarDays :size="17"/>カレンダーで日付を選ぶ <ChevronRight :size="15" :class="{expanded:calendarOpen}"/></button>
   <section class="panel drive-calendar" :class="{expanded:calendarOpen}"><div class="drive-month-heading"><button class="icon-button" @click="moveMonth(-1)" aria-label="前の月"><ChevronLeft :size="18"/></button><strong>{{monthLabel}}</strong><button class="icon-button" @click="moveMonth(1)" aria-label="次の月"><ChevronRight :size="18"/></button></div><div class="drive-calendar-grid"><span v-for="day in weekday" :key="day" class="drive-weekday">{{day}}</span><template v-for="(item,index) in calendarDays" :key="item?.date||'empty'+index"><span v-if="!item" class="calendar-blank"></span><button v-else :class="{selected:item.date===selectedDate,recorded:!!item.data,today:item.date===todayJST()}" :aria-label="`${item.date}${item.data?`、録画${item.data.count}本`:'、録画なし'}`" :aria-current="item.date===selectedDate?'date':undefined" @click="chooseDay(item.date)">{{item.day}}<i v-if="item.data"></i></button></template></div><div class="calendar-legend"><i></i>録画がある日<button class="text-button" @click="chooseDay(todayJST())">今日</button></div></section>
   <section class="panel drive-intervals"><div class="panel-head"><h3>録画されている時間</h3><Clock3 :size="15"/></div><div class="recorded-range-list"><button v-for="interval in availableSpans.slice(0,24)" :key="interval.start" @click="seekAvailable(interval.start,true)"><span>{{clock(interval.start,true)}} — {{clock(interval.end,true)}}</span><ChevronRight :size="14"/></button><p v-if="!availableSpans.length">{{loading?'録画を確認しています…':'日付を選ぶと録画区間が表示されます。'}}</p><p v-else-if="availableSpans.length>24" class="hint">ほか {{availableSpans.length-24}} 区間は時間バーで確認できます。</p></div></section>
  </aside>
  <div class="drive-main"><div v-if="availableSpans.length" class="drive-mobile-intervals" aria-label="録画されている時間"><button v-for="interval in availableSpans" :key="interval.start" @click="seekAvailable(interval.start,true)"><Clock3 :size="13"/>{{clock(interval.start,true)}}<ChevronRight :size="13"/></button></div>
   <section class="panel drive-player-panel"><div class="drive-player-toolbar"><CameraViewSwitch v-model="viewMode" @change="changeView"/><label class="drive-speed">速度<select v-model.number="speed" aria-label="再生速度" @change="changeSpeed"><option :value=".5">0.5×</option><option :value="1">1×</option><option :value="1.5">1.5×</option><option :value="2">2×</option></select></label></div><div class="drive-videos" :class="{dual:viewMode==='both'}"><article v-for="camera in cameras" :key="camera" class="drive-video-slot"><div class="drive-video-label"><span>{{cameraNames[camera]}}</span><span v-if="selected[camera]">{{selected[camera]?.width}} × {{selected[camera]?.height}}</span></div><video v-if="selected[camera]" :key="selected[camera]!.id" :ref="el=>setVideo(camera,el)" :src="streamURL(selected[camera]!)" :muted="camera!==primary" controls playsinline preload="metadata" @loadedmetadata="metadataReady(camera)" @timeupdate="updateTime(camera)" @play="primaryPlay(camera)" @pause="primaryPause(camera)" @ended="ended(camera)" @error="notice='この録画をブラウザーで再生できません。原本をダウンロードして確認してください。'"></video><div v-else class="drive-video-empty"><Film :size="36" stroke-width="1.2"/><h3>{{loading?'録画を確認中…':'この時刻の録画がありません'}}</h3><p>下の時間バーで録画のある区間を選んでください。</p></div><div v-if="selected[camera]" class="drive-clip-footer"><span>{{clock(Date.parse(selected[camera]!.startAt),true)}} — {{clock(Date.parse(selected[camera]!.endAt),true)}} · {{kindLabel(selected[camera]!.kind)}}</span><a :href="downloadURL(selected[camera]!)" class="text-button" :download="selected[camera]!.name" :aria-label="cameraNames[camera]+'の録画原本をダウンロード'"><Download :size="14"/>{{bytes(selected[camera]!.sizeBytes)}}</a></div></article></div><div v-if="notice" class="drive-notice" role="status">{{notice}}</div><div class="drive-audio-note"><Volume2 :size="14"/><span>{{viewMode==='both'?`音声は${cameraNames[primary]}から再生します。`:'音声は録画原本のトラックをそのまま再生します。'}}</span></div></section>
   <section class="panel drive-timeline-panel"><div class="drive-timeline-heading"><div><span class="eyebrow">再生時刻</span><strong>{{clock(cursor||dayStart(selectedDate),true)}}</strong></div><div class="drive-timeline-tools"><button class="icon-button" @click="nextClip(-1)" aria-label="前の録画区間"><ChevronLeft :size="18"/></button><button class="icon-button" @click="nextClip(1)" aria-label="次の録画区間"><ChevronRight :size="18"/></button><label><span>表示範囲</span><select v-model.number="zoomHours" aria-label="時間バーの表示範囲" @change="changeZoom"><option :value="24">24時間</option><option :value="6">6時間</option><option :value="1">1時間</option><option :value=".25">15分</option></select></label><input type="time" step="1" :value="clock(cursor||dayStart(selectedDate),true)" aria-label="再生する時刻を指定" @change="timeInput"></div></div><div class="drive-timeline"><div class="drive-time-ruler"><span v-for="tick in ticks" :key="tick.left" :style="{left:tick.left+'%'}">{{tick.label}}</span></div><div v-for="camera in (['front','in'] as Camera[])" :key="camera" class="drive-timeline-row"><span class="drive-track-name"><i :class="camera"></i>{{camera==='front'?'前方':'車内'}}</span><div class="drive-timeline-lane" :class="camera" tabindex="0" role="slider" :aria-label="cameraNames[camera]+'の録画時間バー'" :aria-valuemin="0" :aria-valuemax="86400" :aria-valuenow="Math.round((cursor-dayStart(selectedDate))/1000)" :aria-valuetext="clock(cursor||dayStart(selectedDate),true)" @pointerdown="pointerDown($event,camera)" @pointermove="pointerMove" @pointerup="pointerUp" @pointercancel="pointer=undefined" @keydown="keySeek($event,camera)"><span v-for="clip in visibleClips(camera)" :key="clip.id" class="drive-recorded-segment" :class="{event:clip.kind==='event',parking:clip.kind==='parking'}" :style="clipStyle(clip)" :title="`${cameraNames[camera]} ${clock(Date.parse(clip.startAt),true)} — ${clock(Date.parse(clip.endAt),true)}`"></span><span class="drive-playhead" :style="{left:cursorPercent+'%'}"><i></i></span></div></div></div><div class="drive-timeline-legend"><span><i class="front"></i>前方の録画</span><span><i class="in"></i>車内の録画</span><span><i class="gap"></i>録画なし</span><p>区間をタップして再生。細かく選ぶときは表示範囲を拡大できます。</p></div></section>
   <p v-if="catalog?.pendingFiles" class="drive-library-note">{{catalog.pendingFiles}} 本は確定待ちです。録画が確定すると時間バーに追加されます。</p><p v-if="catalog?.unreadableFiles" class="drive-library-note">{{catalog.unreadableFiles}} 本の録画情報を読み取れませんでした。必要に応じてSDカード画面から原本を確認してください。</p><p v-if="catalog?.truncated" class="drive-library-note error">録画数の上限に達したため、一部の録画は表示されていません。</p>
  </div>
 </div>
</template>
